Newspaper opening card — minimal, only masthead + headline + rules. No body text, no subhead, no tagline. 6s, 1920x1080, SILENT
```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,400;0,900;1,400&display=swap" rel="stylesheet">
<style>
root{--oxblood:#963f43;--ivory:#e7e0d4;--muted:#9b948a;}
*{margin:0;padding:0;box-sizing:border-box;}
body,#scene{width:1920px;height:1080px;overflow:hidden;background:#0b0d0e;}
#scene{position:relative;display:flex;align-items:center;justify-content:center;}
#bg{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;z-index:1
transform-origin:50% 42%
filter:grayscale(70%) brightness(0.48) sepia(20%);}
#lines{position:absolute;top:0;left:0;width:100%;height:100%;z-index:2
background:repeating-linear-gradient(0deg,transparent,transparent 3px,rgba(0,0,0,0.07) 3px,rgba(0,0,0,0.07) 4px);pointer-events:none;}
#dots{position:absolute;top:0;left:0;width:100%;height:100%;z-index:3
background-image:radial-gradient(circle,rgba(200,180,140,0.06) 1px,transparent 1px)
background-size:5px 5px;pointer-events:none;}
#vig{position:absolute;top:0;left:0;width:100%;height:100%;z-index:4
background:radial-gradient(ellipse at center,transparent 30%,rgba(0,0,0,0.80) 100%);}
#fade{position:absolute;top:0;left:0;width:100%;height:100%;z-index:50;background:#000;opacity:0;pointer-events:none;}
#paper{position:relative;z-index:10;width:960px;display:flex;flex-direction:column;align-items:center;opacity:0;}
/* masthead */
#mhead{width:100%;text-align:center
border-top:2px solid rgba(231,224,212,0.85)
border-bottom:1px solid rgba(231,224,212,0.50)
padding:12px 0 10px;}
#pname{font-family:'Playfair Display',Georgia,serif;font-size:20px;font-weight:400
color:var(--ivory);letter-spacing:0.44em;text-transform:uppercase;}
#dline{font-family:'Playfair Display',Georgia,serif;font-size:12px;font-style:italic
color:var(--muted);letter-spacing:0.14em;margin-top:4px;}
/* thick rule below masthead */
#mbar{width:100%;height:3px;background:rgba(231,224,212,0.80)
margin:8px 0 28px;transform-origin:left;transform:scaleX(0);opacity:0;}
/* headline only */
#hl{font-family:'Playfair Display',Georgia,serif
font-size:96px;font-weight:900
color:var(--ivory);line-height:0.92
letter-spacing:-0.01em;text-align:center
margin-bottom:28px;opacity:0;}
/* bottom thin rule */
#br{width:100%;height:1px;background:rgba(231,224,212,0.35);opacity:0;}
</style>
</head>
<body>
<div id="scene">
<img id="bg" src="{{heroImg}}" alt="">
<div id="lines"></div><div id="dots"></div><div id="vig"></div>
<div id="fade"></div>
<div id="paper">
<div id="mhead">
<div id="pname">The Biographical Record</div>
<div id="dline">London, England &nbsp;·&nbsp; Est. 1976 &nbsp;·&nbsp; A Life in Full</div>
</div>
<div id="mbar"></div>
<div id="hl">BENEDICT<br>CUMBERBATCH</div>
<div id="br"></div>
</div>
</div>
<script src="vendor/gsap.min.js"></script>
<script>
window.addEventListener('DOMContentLoaded',function(){
var tl=gsap.timeline()
tl.fromTo('#bg',{scale:1.0,transformOrigin:'50% 42%'},{scale:1.05,duration:6,ease:'none'},0)
tl.to('#paper',{opacity:1,y:0,duration:0.7,ease:'power3.out',startAt:{opacity:0,y:22}},0.35)
tl.to('#mbar', {opacity:1,scaleX:1,duration:0.55,ease:'expo.out'},0.6)
tl.to('#hl',   {opacity:1,y:0,duration:0.65,ease:'power3.out',startAt:{opacity:0,y:18}},0.95)
tl.to('#br',   {opacity:1,duration:0.4,ease:'power2.out'},1.5)
/* exit */
tl.to('#paper',{opacity:0,y:-20,duration:0.55,ease:'power2.in'},5.1)
tl.to('#fade', {opacity:1,duration:0.7,ease:'power2.inOut'},5.3)
})
</script>
</body>
</html>
